57	@RestController
58	@CrossOrigin(exposedHeaders = "errors, content-type")
59	@RequestMapping("/api")
60	public class OwnerRestControllerV1 implements OwnersApi {
61	
62	    private final ClinicService clinicService;
63	
64	    private final OwnerMapper ownerMapper;
65	
66	    private final PetMapper petMapper;
67	
68	    private final VisitMapper visitMapper;
69	
70	    public OwnerRestControllerV1(ClinicService clinicService,
71	                                 OwnerMapper ownerMapper,
72	                                 PetMapper petMapper,
73	                                 VisitMapper visitMapper) {
74	        this.clinicService = clinicService;
75	        this.ownerMapper = ownerMapper;
76	        this.petMapper = petMapper;
77	        this.visitMapper = visitMapper;
78	    }
79	
80	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
81	    @Override
82	    public ResponseEntity<List<OwnerDto>> listOwners(String lastName) {
83	        Collection<Owner> owners;
84	        if (lastName != null) {
85	            owners = this.clinicService.findOwnerByLastName(lastName);
86	        } else {
87	            owners = this.clinicService.findAllOwners();
88	        }
89	        if (owners.isEmpty()) {
90	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
91	        }
92	        return new ResponseEntity<>(ownerMapper.toOwnerDtoCollection(owners), HttpStatus.OK);
93	    }
94	
95	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
96	    @Override
97	    public ResponseEntity<OwnerDto> getOwner(Integer ownerId) {
98	        Owner owner = this.clinicService.findOwnerById(ownerId);
99	        if (owner == null) {
100	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
101	        }
102	        return new ResponseEntity<>(ownerMapper.toOwnerDto(owner), HttpStatus.OK);
103	    }
104	
105	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
106	    @Override
107	    public ResponseEntity<OwnerDto> addOwner(OwnerFieldsDto ownerFieldsDto) {
108	        String address = normalizeAddress(ownerFieldsDto.getAddress());
109	        List<String> missingFields = new ArrayList<>();
110	        if (isBlank(ownerFieldsDto.getFirstName())) {
111	            missingFields.add("firstName");
112	        }
113	        if (isBlank(ownerFieldsDto.getLastName())) {
114	            missingFields.add("lastName");
115	        }
116	        if (isBlank(address)) {
117	            missingFields.add("address");
118	        }
119	        if (isBlank(ownerFieldsDto.getCity())) {
120	            missingFields.add("city");
121	        }
122	        if (isBlank(ownerFieldsDto.getTelephone())) {
123	            missingFields.add("telephone");
124	        }
125	        if (!missingFields.isEmpty()) {
126	            throw new MissingOwnerFieldsException(missingFields);
127	        }
128	        String telephone = normalizeTelephone(ownerFieldsDto.getTelephone());
129	        if (isTelephoneInUse(telephone)) {
130	            throw new DuplicateTelephoneException(ownerFieldsDto.getTelephone());
131	        }
132	        boolean sharesHousehold = Boolean.TRUE.equals(ownerFieldsDto.getSharesHousehold());
133	        if (!sharesHousehold
134	            && isHouseholdInUse(ownerFieldsDto.getLastName(), address)) {
135	            throw new DuplicateHouseholdException(ownerFieldsDto.getLastName(), address);
136	        }
137	        HttpHeaders headers = new HttpHeaders();
138	        Owner owner = ownerMapper.toOwner(ownerFieldsDto);
139	        owner.setAddress(address);
140	        owner.setTelephone(telephone);
141	        if (owner.getRegistrationDate() == null) {
142	            owner.setRegistrationDate(LocalDate.now());
143	        }
144	        owner.setCustomerCode(nextCustomerCode(owner.getCity(), owner.getLastName()));
145	        owner.setNamesakeCount(namesakeCount(owner.getFirstName(), owner.getLastName()));
146	        if (sharesHousehold) {
147	            owner.setHouseholdId(joinHousehold(owner.getLastName(), owner.getAddress()));
148	        }
149	        this.clinicService.saveOwner(owner);
150	        OwnerDto ownerDto = ownerMapper.toOwnerDto(owner);
151	        headers.setLocation(UriComponentsBuilder.newInstance()
152	            .path("/api/owners/{id}").buildAndExpand(owner.getId()).toUri());
153	        return new ResponseEntity<>(ownerDto, headers, HttpStatus.CREATED);
154	    }
155	
156	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
157	    @Override
158	    public ResponseEntity<OwnerDto> updateOwner(Integer ownerId, OwnerFieldsDto ownerFieldsDto) {
159	        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
160	        if (currentOwner == null) {
161	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
162	        }
163	        currentOwner.setAddress(ownerFieldsDto.getAddress());
164	        currentOwner.setCity(ownerFieldsDto.getCity());
165	        currentOwner.setFirstName(ownerFieldsDto.getFirstName());
166	        currentOwner.setLastName(ownerFieldsDto.getLastName());
167	        currentOwner.setTelephone(normalizeTelephone(ownerFieldsDto.getTelephone()));
168	        this.clinicService.saveOwner(currentOwner);
169	        return new ResponseEntity<>(ownerMapper.toOwnerDto(currentOwner), HttpStatus.NO_CONTENT);
170	    }
171	
172	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
173	    @Transactional
174	    @Override
175	    public ResponseEntity<OwnerDto> deleteOwner(Integer ownerId) {
176	        Owner owner = this.clinicService.findOwnerById(ownerId);
177	        if (owner == null) {
178	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
179	        }
180	        this.clinicService.deleteOwner(owner);
181	        return new ResponseEntity<>(HttpStatus.NO_CONTENT);
182	    }
183	
184	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
185	    @Override
186	    public ResponseEntity<PetDto> addPetToOwner(Integer ownerId, PetFieldsDto petFieldsDto) {
187	        Owner owner = this.clinicService.findOwnerById(ownerId);
188	        if (owner == null) {
189	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
190	        }
191	        HttpHeaders headers = new HttpHeaders();
192	        Pet pet = petMapper.toPet(petFieldsDto);
193	        owner.setId(ownerId);
194	        pet.setOwner(owner);
195	        pet.getType().setName(null);
196	        this.clinicService.savePet(pet);
197	        PetDto petDto = petMapper.toPetDto(pet);
198	        headers.setLocation(UriComponentsBuilder.newInstance().path("/api/pets/{id}")
199	            .buildAndExpand(pet.getId()).toUri());
200	        return new ResponseEntity<>(petDto, headers, HttpStatus.CREATED);
201	    }
202	
203	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
204	    @Override
205	    public ResponseEntity<Void> updateOwnersPet(Integer ownerId, Integer petId, PetFieldsDto petFieldsDto) {
206	        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
207	        if (currentOwner != null) {
208	            Pet currentPet = this.clinicService.findPetById(petId);
209	            if (currentPet != null) {
210	                currentPet.setBirthDate(petFieldsDto.getBirthDate());
211	                currentPet.setName(petFieldsDto.getName());
212	                currentPet.setType(petMapper.toPetType(petFieldsDto.getType()));
213	                this.clinicService.savePet(currentPet);
214	                return new ResponseEntity<>(HttpStatus.NO_CONTENT);
215	            }
216	        }
217	        return new ResponseEntity<>(HttpStatus.NOT_FOUND);
218	    }
219	
220	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
221	    @Override
222	    public ResponseEntity<VisitDto> addVisitToOwner(Integer ownerId, Integer petId, VisitFieldsDto visitFieldsDto) {
223	        HttpHeaders headers = new HttpHeaders();
224	        Visit visit = visitMapper.toVisit(visitFieldsDto);
225	        Pet pet = new Pet();
226	        pet.setId(petId);
227	        visit.setPet(pet);
228	        this.clinicService.saveVisit(visit);
229	        VisitDto visitDto = visitMapper.toVisitDto(visit);
230	        headers.setLocation(UriComponentsBuilder.newInstance().path("/api/visits/{id}")
231	            .buildAndExpand(visit.getId()).toUri());
232	        return new ResponseEntity<>(visitDto, headers, HttpStatus.CREATED);
233	    }
234	
235	
236	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
237	    @Override
238	    public ResponseEntity<PetDto> getOwnersPet(Integer ownerId, Integer petId) {
239	        Owner owner = this.clinicService.findOwnerById(ownerId);
240	        if (owner != null) {
241	            Pet pet = owner.getPet(petId);
242	            if (pet != null) {
243	                return new ResponseEntity<>(petMapper.toPetDto(pet), HttpStatus.OK);
244	            }
245	        }
246	        return new ResponseEntity<>(HttpStatus.NOT_FOUND);
247	    }
248	
249	    private static boolean isBlank(String value) {
250	        return value == null || value.isBlank();
251	    }
252	
253	    /**
254	     * Normalizes a street address into the canonical form stored on and returned for a newly
255	     * created owner. A {@code null} value becomes the empty string; otherwise surrounding
256	     * whitespace is trimmed, internal runs of whitespace are collapsed to a single space, the
257	     * text is upper-cased, and common street-type abbreviations are expanded on a whole-word
258	     * basis ({@code ST -> STREET}, {@code RD -> ROAD}, {@code AVE -> AVENUE}). The normalized
259	     * value is what gets persisted, echoed back, and used for every address comparison (household
260	     * duplicate detection and the shared household identifier).
261	     *
262	     * @param rawAddress the address value as supplied by the client
263	     * @return the normalized address (possibly empty, never {@code null})
264	     */
265	    private static String normalizeAddress(String rawAddress) {
266	        if (rawAddress == null) {
267	            return "";
268	        }
269	        String collapsed = rawAddress.trim().replaceAll("\\s+", " ").toUpperCase(java.util.Locale.ROOT);
270	        if (collapsed.isEmpty()) {
271	            return "";
272	        }
273	        String[] tokens = collapsed.split(" ");
274	        StringBuilder sb = new StringBuilder(collapsed.length());
275	        for (int i = 0; i < tokens.length; i++) {
276	            String token = tokens[i];
277	            switch (token) {
278	                case "ST" -> token = "STREET";
279	                case "RD" -> token = "ROAD";
280	                case "AVE" -> token = "AVENUE";
281	                default -> { }
282	            }
283	            if (i > 0) {
284	                sb.append(' ');
285	            }
286	            sb.append(token);
287	        }
288	        return sb.toString();
289	    }
290	
291	    /**
292	     * Builds the customer code assigned to a newly created owner. The code is formatted
293	     * {@code <CITY3>-<LAST3>-<NNNN>} where {@code CITY3} is the upper-cased first three letters
294	     * of the owner's city, {@code LAST3} is the upper-cased first three letters of the owner's
295	     * last name and {@code NNNN} is a per-city 4-digit zero-padded sequence equal to one more
296	     * than the number of owners already in that city (e.g. {@code LON-SMI-0007}).
297	     *
298	     * @param city the city of the owner being created
299	     * @param lastName the last name of the owner being created
300	     * @return the customer code to assign
301	     */
302	    private String nextCustomerCode(String city, String lastName) {
303	        String city3 = letterPrefix3(city);
304	        String last3 = letterPrefix3(lastName);
305	        String normalizedCity = normalizeIdentity(city);
306	        long sequence = this.clinicService.findAllOwners().stream()
307	            .filter(existing -> normalizeIdentity(existing.getCity()).equals(normalizedCity))
308	            .count() + 1L;
309	        return String.format("%s-%s-%04d", city3, last3, sequence);
310	    }
311	
312	    /**
313	     * Returns the upper-cased first three letters of the given value, skipping any non-letter
314	     * characters. Values with fewer than three letters yield a shorter prefix.
315	     *
316	     * @param value the source text
317	     * @return the upper-cased letter prefix (at most three characters, never {@code null})
318	     */
319	    private static String letterPrefix3(String value) {
320	        StringBuilder prefix = new StringBuilder(3);
321	        if (value != null) {
322	            for (int i = 0; i < value.length() && prefix.length() < 3; i++) {
323	                char c = value.charAt(i);
324	                if (Character.isLetter(c)) {
325	                    prefix.append(Character.toUpperCase(c));
326	                }
327	            }
328	        }
329	        return prefix.toString();
330	    }
331	
332	    /**
333	     * Normalizes a telephone into E.164 form. Spaces, dashes and brackets are stripped. A value
334	     * already carrying a leading {@code '+'} keeps its country code; otherwise country code
335	     * {@code +61} is assumed and a single leading {@code '0'} is dropped from the national digits.
336	     * The result must carry a leading {@code '+'} followed by 8 to 15 digits.
337	     *
338	     * @param rawTelephone the telephone value as supplied by the client
339	     * @return the telephone in E.164 form (e.g. {@code +61412345678})
340	     * @throws InvalidTelephoneException if the value cannot form a valid E.164 number
341	     */
342	    private static String normalizeTelephone(String rawTelephone) {
343	        if (rawTelephone == null) {
344	            throw new InvalidTelephoneException(rawTelephone);
345	        }
346	        String cleaned = rawTelephone.replaceAll("[\\s\\-()]", "");
347	        String e164;
348	        if (cleaned.startsWith("+")) {
349	            String digits = cleaned.substring(1);
350	            if (!digits.matches("[0-9]+")) {
351	                throw new InvalidTelephoneException(rawTelephone);
352	            }
353	            e164 = "+" + digits;
354	        } else {
355	            if (!cleaned.matches("[0-9]+")) {
356	                throw new InvalidTelephoneException(rawTelephone);
357	            }
358	            String national = cleaned.startsWith("0") ? cleaned.substring(1) : cleaned;
359	            e164 = "+61" + national;
360	        }
361	        int digitCount = e164.length() - 1;
362	        if (digitCount < 8 || digitCount > 15) {
363	            throw new InvalidTelephoneException(rawTelephone);
364	        }
365	        return e164;
366	    }
367	
368	    /**
369	     * Determines whether any existing owner already uses the given E.164 telephone. Stored
370	     * telephones are themselves E.164, so the values are compared directly.
371	     *
372	     * @param e164Telephone the E.164 telephone of the owner being created
373	     * @return {@code true} if another owner already has the same E.164 telephone
374	     */
375	    private boolean isTelephoneInUse(String e164Telephone) {
376	        return this.clinicService.findAllOwners().stream()
377	            .map(Owner::getTelephone)
378	            .filter(existing -> existing != null)
379	            .anyMatch(e164Telephone::equals);
380	    }
381	
382	    /**
383	     * Determines whether any existing owner already shares a household with the owner being created,
384	     * i.e. has both the same last name and the same address. Both fields are compared
385	     * case-insensitively after collapsing runs of whitespace to a single space and trimming.
386	     *
387	     * @param lastName the last name of the owner being created
388	     * @param address the address of the owner being created
389	     * @return {@code true} if another owner already has the same last name and address
390	     */
391	    private boolean isHouseholdInUse(String lastName, String address) {
392	        String normalizedLastName = normalizeIdentity(lastName);
393	        String normalizedAddress = normalizeIdentity(address);
394	        return this.clinicService.findAllOwners().stream()
395	            .anyMatch(existing -> normalizeIdentity(existing.getLastName()).equals(normalizedLastName)
396	                && normalizeIdentity(existing.getAddress()).equals(normalizedAddress));
397	    }
398	
399	    /**
400	     * Counts how many existing owners already share the given first name and last name with the
401	     * owner being created. Both names are compared case-insensitively (after trimming and
402	     * collapsing runs of whitespace). The count reflects the state before the new owner is
403	     * persisted, so a first, otherwise-unique owner yields {@code 0}.
404	     *
405	     * @param firstName the first name of the owner being created
406	     * @param lastName the last name of the owner being created
407	     * @return the number of existing owners sharing the same first and last name
408	     */
409	    private int namesakeCount(String firstName, String lastName) {
410	        String normalizedFirstName = normalizeIdentity(firstName);
411	        String normalizedLastName = normalizeIdentity(lastName);
412	        return (int) this.clinicService.findAllOwners().stream()
413	            .filter(existing -> normalizeIdentity(existing.getFirstName()).equals(normalizedFirstName)
414	                && normalizeIdentity(existing.getLastName()).equals(normalizedLastName))
415	            .count();
416	    }
417	
418	    /**
419	     * Assigns the owner being created to the household identified by the given last name and
420	     * address and returns the household's stable shared identifier. The identifier is derived
421	     * deterministically from the normalized last name and address, so every member of the same
422	     * household resolves to the same value regardless of creation order. Any existing member that
423	     * does not yet carry the identifier is back-filled so all household members share it.
424	     *
425	     * @param lastName the last name of the owner being created
426	     * @param address the address of the owner being created
427	     * @return the stable household identifier shared by all members of the household
428	     */
429	    private String joinHousehold(String lastName, String address) {
430	        String householdId = householdIdFor(lastName, address);
431	        String normalizedLastName = normalizeIdentity(lastName);
432	        String normalizedAddress = normalizeIdentity(address);
433	        for (Owner existing : this.clinicService.findAllOwners()) {
434	            if (normalizeIdentity(existing.getLastName()).equals(normalizedLastName)
435	                && normalizeIdentity(existing.getAddress()).equals(normalizedAddress)
436	                && !householdId.equals(existing.getHouseholdId())) {
437	                existing.setHouseholdId(householdId);
438	                this.clinicService.saveOwner(existing);
439	            }
440	        }
441	        return householdId;
442	    }
443	
444	    /**
445	     * Derives the stable household identifier for a given last name and address. The value is the
446	     * first 16 upper-case hex characters of the SHA-256 digest of the normalized last name and
447	     * address, so it is stable across calls and identical for every member of the household.
448	     *
449	     * @param lastName the last name of the household
450	     * @param address the address of the household
451	     * @return the stable household identifier
452	     */
453	    private static String householdIdFor(String lastName, String address) {
454	        String key = normalizeIdentity(lastName) + "\n" + normalizeIdentity(address);
455	        try {
456	            byte[] digest = java.security.MessageDigest.getInstance("SHA-256")
457	                .digest(key.getBytes(java.nio.charset.StandardCharsets.UTF_8));
458	            StringBuilder sb = new StringBuilder(digest.length * 2);
459	            for (byte b : digest) {
460	                sb.append(String.format("%02x", b));
461	            }
462	            return sb.substring(0, 16).toUpperCase(java.util.Locale.ROOT);
463	        }
464	        catch (java.security.NoSuchAlgorithmException e) {
465	            throw new IllegalStateException("SHA-256 not available", e);
466	        }
467	    }
468	
469	    /**
470	     * Normalizes a text field for household-identity comparison: {@code null} becomes the empty
471	     * string, surrounding whitespace is trimmed, internal runs of whitespace are collapsed to a
472	     * single space, and the result is lower-cased.
473	     *
474	     * @param value the raw field value
475	     * @return the normalized value used for case-insensitive, whitespace-insensitive comparison
476	     */
477	    private static String normalizeIdentity(String value) {
478	        if (value == null) {
479	            return "";
480	        }
481	        return value.trim().replaceAll("\\s+", " ").toLowerCase(java.util.Locale.ROOT);
482	    }
483	}
